    "key_concepts": [
      {
        "name": "面试反问技巧",
        "definition": "当面试官问“你有什么问题要问我”时，应聘者应提出基于对方、回到自己、双方双赢的问题，以展示认真负责的态度和对雇主的重视。",
        "importance": "核心方法论，将面试收尾的常规问题转化为加分项，揭示了面试官的考察意图。",
        "in_wiki": false
      },
      {
        "name": "失败经历回答法",
        "definition": "回答“最失败的经历”时，重点不在于描述失败本身，而在于展示抗压能力、从错误中学习的能力，并将重点放在分析原因和收获上，对事不对人。",
        "importance": "针对高频压力面试题的具体应对策略，强调将负面经历转化为正面成长证据。",
        "in_wiki": false
      },
      {
        "name": "面试压力测试",
        "definition": "面试不仅是求职，也可视为对个人竞争力的压力测试和思考实验。",
        "importance": "提供了看待面试的新视角，鼓励即使不找工作的人也进行自我检验。",
        "in_wiki": false
      },
      {
        "name": "基于对方、回到自己、双方双赢",
        "definition": "提出高质量面试问题的三要素：问题需基于对雇主的最新了解，关联到自身岗位和职业发展，并体现积极双赢的姿态。",
        "importance": "马萍锦囊的核心框架，为构建面试问题提供了具体、可操作的标准。",
        "in_wiki": false
      }
    ],
    "main_arguments": [
      {
        "claim": "面试官问“你有什么问题要问我”是一个关键的区分性压力测试，而非简单的流程收尾。",
        "evidence": "脱不花分享个人作为面试官的经验：对100%通过或不通过的候选人不会问此问题，问此问题意味着候选人处于60分的纠结状态。",
        "strength": "中等，基于个人经验分享，非系统性研究，但提供了面试官视角的一手信息。",
        "subject": "面试反问环节"
      },
      {
        "claim": "回答“最失败的经历”时，应选择一个虽然失败但让自己获得进步的事件，并重点分析原因和收获，对事不对人。",
        "evidence": "池净的锦囊建议，以及乔文雅分享考研失败后完成高质量毕业设计并获得offer的成功案例。",
        "strength": "中等，结合了专家建议和具体成功案例，但案例为个例。",
        "subject": "失败经历面试题"
      },
      {
        "claim": "面试提问应遵循“基于对方、回到自己、双方双赢”的三要素原则。",
        "evidence": "马萍的锦囊建议，并提供了针对公司和面试官角度的具体提问范例。",
        "strength": "中等，提供了清晰框架和范例，但属于经验性建议。",
        "subject": "面试反问技巧"
      }
    ],
    "connections_to_existing_wiki": "本期内容与已有的[[entities/脱不花]]、[[entities/得到锦囊]]直接相关。内容上，与[[concepts/靠谱]]、[[concepts/沟通主动性与资源调用]]等职场沟通概念有内在联系，但提供了更具体、场景化的面试技巧。",
    "contradictions_and_tensions": "文中未发现与现有Wiki内容的直接矛盾。内部存在一个隐含的张力：面试技巧（如精心准备问题）与真诚展示自我之间的平衡，但文中通过强调“认真和诚意”而非“面试表演”来尝试调和。",
    "recommendations": {
